function validate(input) {
  const [{ Actions = [], Removals = [] }] = input;
  const kinds = ['view', 'like', 'reaction', 'comment', 'report', 'share'];
  const isDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d);
  for (const [user, post, date, action, extra] of Actions) {
    if (user === null || post === null || date === null || action === null) return 'user_id, post_id, action_date and action are required.';
    if (!kinds.includes(action)) return `Unknown action ${action}.`;
    if (!isDate(date)) return `action_date ${date} is not YYYY-MM-DD.`;
    if (action === 'report' && extra === null) return 'A report needs a reason in extra.';
  }
  const removed = new Set();
  for (const [post, date] of Removals) {
    if (post === null || date === null) return 'post_id and remove_date are required.';
    if (removed.has(post)) return `post_id ${post} appears twice in Removals.`;
    if (!isDate(date)) return `remove_date ${date} is not YYYY-MM-DD.`;
    removed.add(post);
  }
  return null;
}

