function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const kinds = ['view', 'like', 'reaction', 'comment', 'report', 'report', 'report', 'share'];
  const reasons = ['spam', 'spam', 'racism', 'violence'];
  const moods = ['love', 'wow', null];
  const date = (month, d) => `2019-${month}-${String(d).padStart(2, '0')}`;
  const days = small ? 4 : 28, posts = small ? 5 : 400, users = small ? 4 : 300, rows = small ? pick(9) : 1900;
  const Actions = [];
  for (let i = 0; i < rows; i++) {
    if (Actions.length && rand() < 0.15) { Actions.push([...Actions[pick(Actions.length)]]); continue; }
    const action = kinds[pick(kinds.length)];
    const extra = action === 'report' ? reasons[pick(reasons.length)] : action === 'reaction' ? moods[pick(moods.length)] : null;
    Actions.push([1 + pick(users), 1 + pick(posts), date('07', 1 + pick(days)), action, extra]);
  }
  // Removed posts include some never reported (post posts + 1 never appears in Actions); dates fall before and after reports.
  const Removals = [], removed = new Set();
  for (let post = 1; post <= posts + 1; post++) if (rand() < 0.4) { removed.add(post); Removals.push([post, date('07', 1 + pick(days + 3))]); }
  const average = () => {
    const byDay = new Map();
    for (const [, post, day, action, extra] of Actions) {
      if (action !== 'report' || extra !== 'spam') continue;
      if (!byDay.has(day)) byDay.set(day, new Set());
      byDay.get(day).add(post);
    }
    if (!byDay.size) return null;
    let sum = 0;
    for (const set of byDay.values()) sum += 100 * [...set].filter(p => removed.has(p)).length / set.size;
    return sum / byDay.size;
  };
  // Keep the answer clear of a rounding tie at the third decimal, where float and MySQL decimal arithmetic could
  // disagree: each extra day with one unremoved spam report changes the average.
  for (let extraDay = 1; extraDay < 28; extraDay++) {
    const value = average();
    if (value === null || Math.abs((value * 100) % 1 - 0.5) > 0.01) break;
    Actions.push([1, posts + 1 + extraDay, date('08', extraDay), 'report', 'spam']);
  }
  return [{ Actions, Removals }];
}
